{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF mixture weight",
      "description": "Weights the model-based and model-free Q-values to compute the net Q-value for Stage 1.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice stickiness",
      "description": "Adds a bonus to the Stage 1 logits for the action chosen in the previous trial.",
      "params": [
        {
          "name": "st",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "stickiness = np.zeros(2)\n        if last_action_1 != -1:\n            stickiness[last_action_1] = 1.0\n            \n        logits_1 = beta_1 * q_net + st * stickiness",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility trace",
      "description": "Updates the Stage 1 model-free Q-value using the Stage 2 reward prediction error, scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[a1] += alpha * delta_stage1 + alpha * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value decay/forgetting",
      "description": "Decays the Q-values of unchosen actions towards a neutral value of 0.5 over time.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[1 - a1] = (1 - decay) * q_stage1_mf[1 - a1] + decay * 0.5\n        for s in range(2):\n            for a in range(2):\n                if not (s == state_idx and a == a2):\n                    q_stage2_mf[s, a] = (1 - decay) * q_stage2_mf[s, a] + decay * 0.5",
      "expressible_in_slots": true
    },
    {
      "name": "neutral_q_initialization",
      "title": "Neutral Q initialization",
      "description": "Initializes the model-free Q-values for both stages to 0.5.",
      "params": [],
      "evidence": "q_stage1_mf = np.ones(2) * 0.5\n    q_stage2_mf = np.ones((2, 2)) * 0.5",
      "expressible_in_slots": true
    }
  ]
}
